const GoogleCloudDialogflowCxV3ResponseMessageSchema: z.ZodType<GoogleCloudDialogflowCxV3ResponseMessageType> =
  z
    .object({
      channel: z
        .string()
        .exactOptional()
        .openapi({
          description:
            'The channel which the response is associated with. Clients can specify the channel via QueryParameters.channel, and only associated channel response will be returned.',
        }),
      conversationSuccess:
        GoogleCloudDialogflowCxV3ResponseMessageConversationSuccessSchema.exactOptional().openapi({
          description: 'Indicates that the conversation succeeded.',
        }),
      endInteraction:
        GoogleCloudDialogflowCxV3ResponseMessageEndInteractionSchema.exactOptional().openapi({
          description:
            "Output only. A signal that indicates the interaction with the Dialogflow agent has ended. This message is generated by Dialogflow only when the conversation reaches `END_SESSION` page. It is not supposed to be defined by the user. It's guaranteed that there is at most one such message in each response.",
          readOnly: true,
        }),
      liveAgentHandoff:
        GoogleCloudDialogflowCxV3ResponseMessageLiveAgentHandoffSchema.exactOptional().openapi({
          description: 'Hands off conversation to a human agent.',
        }),
      mixedAudio: GoogleCloudDialogflowCxV3ResponseMessageMixedAudioSchema.exactOptional().openapi({
        description:
          'Output only. An audio response message composed of both the synthesized Dialogflow agent responses and responses defined via play_audio. This message is generated by Dialogflow only and not supposed to be defined by the user.',
        readOnly: true,
      }),
      outputAudioText:
        GoogleCloudDialogflowCxV3ResponseMessageOutputAudioTextSchema.exactOptional().openapi({
          description:
            'A text or ssml response that is preferentially used for TTS output audio synthesis, as described in the comment on the ResponseMessage message.',
        }),
      payload: z
        .record(z.string(), z.any().openapi({ description: 'Properties of the object.' }))
        .exactOptional()
        .openapi({
          description: 'Returns a response containing a custom, platform-specific payload.',
        }),
      playAudio: GoogleCloudDialogflowCxV3ResponseMessagePlayAudioSchema.exactOptional().openapi({
        description:
          'Signal that the client should play an audio clip hosted at a client-specific URI. Dialogflow uses this to construct mixed_audio. However, Dialogflow itself does not try to read or process the URI in any way.',
      }),
      telephonyTransferCall:
        GoogleCloudDialogflowCxV3ResponseMessageTelephonyTransferCallSchema.exactOptional().openapi(
          {
            description:
              'A signal that the client should transfer the phone call connected to this agent to a third-party endpoint.',
          },
        ),
      text: GoogleCloudDialogflowCxV3ResponseMessageTextSchema.exactOptional().openapi({
        description: 'Returns a text response.',
      }),
    })
    .openapi({
      description:
        'Represents a response message that can be returned by a conversational agent. Response messages are also used for output audio synthesis. The approach is as follows: * If at least one OutputAudioText response is present, then all OutputAudioText responses are linearly concatenated, and the result is used for output audio synthesis. * If the OutputAudioText responses are a mixture of text and SSML, then the concatenated result is treated as SSML; otherwise, the result is treated as either text or SSML as appropriate. The agent designer should ideally use either text or SSML consistently throughout the bot design. * Otherwise, all Text responses are linearly concatenated, and the result is used for output audio synthesis. This approach allows for more sophisticated user experience scenarios, where the text displayed to the user may differ from what is heard.',
      required: [],
    })
    .openapi('GoogleCloudDialogflowCxV3ResponseMessage')

